import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Qt.html","title":"Qt","lang":"en-US","frontmatter":{},"git":{"createdTime":1664611463000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":9}]},"readingTime":{"minutes":0.7,"words":210},"filePathRelative":"Qt.md"}`),a={name:`Qt.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="qt" tabindex="-1"><a class="header-anchor" href="#qt"><span>Qt</span></a></h1><p>Qt関連のリンクとかを貼っておく場所。</p><ul><li><a href="https://doc.qt.io/qt-6/" target="_blank" rel="noopener noreferrer">Qt 6.9</a> 公式ドキュメント</li><li><a href="https://qiita.com/Chironian/items/acb465f388aa75f5d6a5" target="_blank" rel="noopener noreferrer">Windows 7でQt5.4.0をビルドする。その２(Qt 64bitビルド) - Qiita</a></li><li><a href="https://www.kdab.com/wp-content/uploads/stories/multithreading-with-qt-1.pdf" target="_blank" rel="noopener noreferrer">Multithreading with Qt(pdf)</a> QtのthreadとSTLのmutex等を混ぜられると言っているが、本当だろうか？</li><li><a href="https://www.copperspice.com/" target="_blank" rel="noopener noreferrer">CopperSpice</a> forkしてC++っぽくしている奴。良いかも？</li><li><a href="https://karino2.github.io/2025/04/22/qt_vcpkg_cmake.html" target="_blank" rel="noopener noreferrer">qt-cmakeとvcpkgの共存 - なーんだ、ただの水たまりじゃないか</a></li></ul><h2 id="qmlデバッガに接続出来ませんでした、的なエラー" tabindex="-1"><a class="header-anchor" href="#qmlデバッガに接続出来ませんでした、的なエラー"><span>QMLデバッガに接続出来ませんでした、的なエラー</span></a></h2><p>プロジェクト＞ビルドと実行の下のキット＞実行 の中にDebugger settingsというのがあって、ここのQML debuggerを無効にすると無くせる。</p><p>ビルドの方ばかり見ていたが実行の方だった。</p><h2 id="windowsでのパラレルビルド" tabindex="-1"><a class="header-anchor" href="#windowsでのパラレルビルド"><span>Windowsでのパラレルビルド</span></a></h2><p>おおむね以下が正しいが、jom.exeが無い。 <a href="https://forum.qt.io/topic/70247/parallel-multi-cpu-multi-core-build/5" target="_blank" rel="noopener noreferrer">parallel multi-cpu multi-core build - Qt Forum</a></p><p>jom.exeを手動で入れる。</p><p><a href="https://forum.qt.io/topic/121491/jom-exe-is-missing/2" target="_blank" rel="noopener noreferrer">jom.exe is missing - Qt Forum</a></p><p>そしてプロジェクトからビルドと実行の使ってるキットの実行で、nmake.exeの代わりに実行するコマンド、 でさきほどダウンロードしたjom.exeを指定したらできた。</p><h2 id="qtextcharformatのcopy-assignment" tabindex="-1"><a class="header-anchor" href="#qtextcharformatのcopy-assignment"><span>QTextCharFormatのcopy assignment</span></a></h2><p><a href="https://doc.qt.io/qt-6/qtextcharformat.html" target="_blank" rel="noopener noreferrer">QTextCharFormat Class - Qt GUI 6.6.1</a>　を見ていたら、copy assignmentがないように見えるが、 ホバーでツールチップをみると定義されているように見える。 このケースではデフォルトのcopy assignmentが定義されて、baseのcopy assignmentが呼ばれるっぽいか？ ドキュメントからわからないってどうなの？と思ってしまうが。</p><h2 id="qlistviewとqlistwidget" tabindex="-1"><a class="header-anchor" href="#qlistviewとqlistwidget"><span>QListViewとQListWidget</span></a></h2><p>QListViewでカスタムなwidgetをアイテムごとに設定出来ないかなぁ、と調べていたら、昔のQListWidgetの方はその辺がちゃんとある事を知る。これは酷い。</p><p><a href="https://runebook.dev/en/articles/qt/qlistwidget/itemWidget" target="_blank" rel="noopener noreferrer">Qt List Widget Customization: itemWidget vs. Delegates vs. Custom Models</a></p><h2 id="qt5のビルド調査" tabindex="-1"><a class="header-anchor" href="#qt5のビルド調査"><span>Qt5のビルド調査</span></a></h2><p>Qt5をカスタムでビルドして使っているオープンソースも多く見えるが、みんなどうしているんだろう？ 以下を見たら、vcpkgがあるとの事。</p><p><a href="https://raymii.org/s/tutorials/Qt_5.15_LTS_on_Windows_without_a_Qt_Account.html" target="_blank" rel="noopener noreferrer">Qt 5.15 LTS on Windows without a Qt Account - Raymii.org</a></p><p>やってみよう。</p><p>長くなったので別ページへ。<a href="./vcpkgでQt5.html">vcpkgでQt5</a></p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};